891	function successorChainWorkflow(size = LONG_CHAIN_SIZE) {
892	  const nodes = [{ id: 'n0', type: 'trigger', next: 'n1' }];
893	  for (let i = 1; i < size - 1; i += 1) {
894	    nodes.push({ id: `n${i}`, type: 'action', next: `n${i + 1}` });
