900	// The ordering chain is carried by explicit dependencies: d1 may run only
901	// after d0, d2 only after d1, and so on; successor edges just converge on
902	// the single end node.
903	function dependencyChainWorkflow(size = LONG_CHAIN_SIZE) {
904	  const nodes = [{ id: 'd0', type: 'trigger', next: 'done' }];
905	  for (let i = 1; i < size; i += 1) {
906	    nodes.push({ id: `d${i}`, type: 'action', dependsOn: [`d${i - 1}`], next: 'done' });
907	  }
908	  nodes.push({ id: 'done', type: 'end', result: 'done' });
909	  return { id: 'long-dependency-chain', entry: 'd0', nodes };
910	}
