import { validateWorkflow } from './src/engine.js';

const base = (mutate) => {
  const w = {
    id: 'x', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'done' },
      { id: 'done', type: 'end', result: 'done' },
    ],
  };
  mutate(w);
  return w;
};

const cases = [
  // next array: empty, non-string, duplicate, unknown — original wording
  [w => { w.nodes[0].next = []; }, 'next array must not be empty'],
  [w => { w.nodes[0].next = [5]; }, 'next array entries must be node id strings'],
  [w => { w.nodes[0].next = ['done', 'done']; }, 'duplicate destination done'],
  [w => { w.nodes[0].next = ['ghost']; }, 'points to an unknown destination'],
  // multiple problems: earlier entry/error wins
  [w => { w.nodes[0].next = [null, 'ghost']; }, 'must be node id strings'],
  [w => { w.nodes[0].next = ['ghost', 'ghost']; }, 'unknown destination'],
  // dependsOn: non-array, non-string, duplicate, unknown, self, entry
  [w => { w.nodes[0].dependsOn = 'done'; }, 'dependsOn must be an array'],
  [w => { w.nodes[0].dependsOn = [null]; }, 'dependsOn entries must be node id strings'],
  [w => { w.nodes[1].dependsOn = ['start', 'start']; }, 'duplicate dependency start'],
  [w => { w.nodes[1].dependsOn = ['ghost']; }, 'depends on an unknown node'],
  [w => { w.nodes[1].dependsOn = ['done']; }, 'must not depend on itself'],
  [w => { w.nodes[0].dependsOn = ['done']; }, 'entry node start must not declare dependencies'],
  // self vs unknown ordering (self on an earlier entry wins over a later unknown)
  [w => { w.nodes[1].dependsOn = ['done', 'ghost']; }, 'must not depend on itself'],
  [w => { w.nodes[1].dependsOn = ['ghost', 'done']; }, 'depends on an unknown node'],
];

let failures = 0;
for (const [mutate, expected] of cases) {
  try {
    validateWorkflow(base(mutate));
    console.log('FAIL (no throw):', expected);
    failures++;
  } catch (error) {
    if (!error.message.includes(expected)) {
      console.log('FAIL:', JSON.stringify(expected), '=> got:', error.message);
      failures++;
    } else {
      console.log('ok:', expected);
    }
  }
}

// Legal array: accepted in declaration order; caller's array/node untouched.
const good = {
  id: 'g', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: ['b', 'a', 'c'] },
    { id: 'a', type: 'action', message: 'a', dependsOn: ['c', 'b'], next: 'end' },
    { id: 'b', type: 'action', message: 'b', next: 'end' },
    { id: 'c', type: 'action', message: 'c', next: 'end' },
    { id: 'end', type: 'end', result: 'ok' },
  ],
};
